# Unit test for method get_args_from_task_vars of class ActionModule
def test_ActionModule_get_args_from_task_vars(mocker):
    action = ActionModule.__new__(ActionModule)
    action._templar = mocker.Mock()

    argument_spec = {
        'username': {'type': 'str'},
        'port': {'type': 'int'},
        'missing_argument': {'type': 'str'},
    }
    task_vars = {
        'username': '{{ actual_username }}',
        'actual_username': 'alice',
        'port': 22,
        'unrelated_variable': 'ignored',
    }

    expected_untemplated_args = {
        'username': '{{ actual_username }}',
        'port': 22,
    }
    expected_args = {
        'username': 'alice',
        'port': 22,
    }

    action._templar.template.return_value = expected_args

    result = action.get_args_from_task_vars(argument_spec, task_vars)

    action._templar.template.assert_called_once_with(expected_untemplated_args)
    assert result == expected_args
